def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    for color in range(1, 10):
        pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        # Use two adjacent diagonal markers to determine the ray direction.
        for i, (r1, c1) in enumerate(pts):
            for r2, c2 in pts[i + 1:]:
                dr, dc = r2 - r1, c2 - c1
                if abs(dr) == abs(dc) and dr != 0:
                    # Extend beyond the later marker in row-major order.
                    r, c = r2 + dr, c2 + dc
                    while 0 <= r < h and 0 <= c < w:
                        out[r][c] = color
                        r += dr
                        c += dc
                    return out
    return out
